const html = $input.first().json.data ?? $input.first().json.body ?? '';

const matches = [...html.matchAll(/<h3>(.*?)<\/h3>|<span>(.*?)<\/span>|<p>(.*?)<\/p>|<small>(.*?)<\/small>/gs)];

const textoPuro = matches
  .map(m => (m[1] || m[2] || m[3] || m[4] || '').replace(/<[^>]+>/g, '').trim())
  .filter(t => t.length > 3 && t.length < 300)
  .join('\n');

const textoLimpio = textoPuro
  .slice(0, 12000)
  .replace(/[^\x00-\x7FáéíóúÁÉÍÓÚñÑüÜ¡¿.,;:%()\-\n\r ]/g, '');

return [{ json: { html_limpio: JSON.stringify(textoLimpio).slice(1, -1) } }];

function simpleHash(str) {
  let h = 0;
  for (let i = 0; i < str.length; i++) {
    h = Math.imul(31, h) + str.charCodeAt(i) | 0;
  }
  return Math.abs(h).toString(16).padStart(8,'0');
}

// Banco/billetera FIJO inyectado por el workflow (nodo Config Fuente).
const banco_billetera = $('Config Fuente').first().json.banco_billetera ?? null;

const raw = $input.first().json;
const payload = raw.choices?.[0]?.message?.content ?? raw.message?.content ?? raw.text ?? raw.response ?? JSON.stringify(raw);

let parsed;
try {
  const stripped = (typeof payload === 'string' ? payload : JSON.stringify(payload))
    .replace(/^```json\s*/m, '').replace(/\s*```\s*$/m, '').trim();
  parsed = JSON.parse(stripped);
} catch (e) { parsed = { promos: [] }; }

const promos = Array.isArray(parsed) ? parsed : (parsed.promos ?? []);

// Mapa de canonicalizacion de COMERCIOS conocidos.
const CANON = {
  'ypf': 'YPF', 'axion': 'Axion', 'shell': 'Shell',
  'farmacity': 'Farmacity', 'starbucks': 'Starbucks',
  'tea connection': 'Tea Connection', 'nike': 'Nike',
  'adidas': 'Adidas', 'dexter': 'Dexter',
  'coto': 'Coto', 'carrefour': 'Carrefour', 'jumbo': 'Jumbo',
  'dia': 'Dia', 'disco': 'Disco', 'vea': 'Vea',
  'mercado libre': 'Mercado Libre', 'mercadolibre': 'Mercado Libre',
  'easy': 'Easy', 'garbarino': 'Garbarino', 'fravega': 'Frávega',
  'musimundo': 'Musimundo', 'rappi': 'Rappi', 'pedidosya': 'PedidosYa'
};

function canonComercio(m) {
  if (!m) return null;
  const k = String(m).trim().toLowerCase();
  return CANON[k] ?? (m.charAt(0).toUpperCase() + m.slice(1));
}

const out = [];
for (const p of promos) {
  const comercio = canonComercio(p.comercio);
  if (!comercio) continue;

  const dias = Array.isArray(p.dias) ? p.dias : (p.dias ? [p.dias] : null);

  const content = [
    banco_billetera ? `Banco/Billetera: ${banco_billetera}` : '',
    `Comercio: ${comercio}`,
    p.titulo ? `Promo: ${p.titulo}` : '',
    p.descuento_pct != null ? `Descuento: ${p.descuento_pct}%` : '',
    p.medio_pago ? `Medio de pago: ${p.medio_pago}` : '',
    dias ? `Dias: ${dias.join(', ')}` : '',
    p.tope_reintegro ? `Tope: ${p.tope_reintegro}` : '',
    p.fecha_hasta ? `Vigente hasta: ${p.fecha_hasta}` : '',
    p.descripcion ? `Detalle: ${p.descripcion}` : ''
  ].filter(Boolean).join('. ');

  const hashInput = [
    banco_billetera ?? '',
    comercio,
    p.medio_pago ?? '',
    p.titulo ?? '',
    p.fecha_hasta ?? ''
  ].join('|');
  const content_hash = simpleHash(hashInput);

  out.push({ json: {
    comercio,
    banco_billetera,
    rubro: p.rubro ?? null,
    titulo: p.titulo ?? null,
    descripcion: p.descripcion ?? null,
    descuento_pct: p.descuento_pct ?? null,
    medio_pago: p.medio_pago ?? null,
    dias,
    tope_reintegro: p.tope_reintegro ?? null,
    fecha_desde: p.fecha_desde ?? null,
    fecha_hasta: p.fecha_hasta ?? null,
    fuente_url: p.fuente_url ?? null,
    content,
    content_hash
  }});
}

return out;

// Une CADA fila normalizada con SU embedding correspondiente.
const normItems = $('Normalizar + content_hash (Function)').all();
const embItems = $input.all();

const out = [];
for (let i = 0; i < normItems.length; i++) {
  const row = normItems[i].json;
  const emb = embItems[i]?.json ?? {};
  const embedding = emb.data?.[0]?.embedding ?? emb.embedding ?? emb.vector ?? null;
  out.push({ json: { ...row, embedding } });
}

return out;

// Placeholder de notificacion de errores.
// Conectar aqui (rama de error) un nodo de Slack/Email/Telegram para
// avisar si fallo la ingesta de algun comercio/banco.
return $input.all();
